alter table public.timeline_daw_normalization_render_jobs add column if not exists failure_class text check(failure_class in('retryable','terminal')),add column if not exists next_attempt_at timestamptz;
create table if not exists public.timeline_daw_normalization_alerts(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,kind text not null check(kind in('stale-lease','repeated-failure','terminal-failure','approval-stale','prune-failure','cron-stale')),severity text not null check(severity in('warning','critical')),message text not null,state text not null default 'open' check(state in('open','acknowledged','resolved')),context jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.timeline_daw_normalization_alerts enable row level security;create policy timeline_daw_normalization_alerts_owner on public.timeline_daw_normalization_alerts for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create table if not exists public.timeline_daw_normalization_operator_receipts(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,alert_id text references public.timeline_daw_normalization_alerts(id) on delete set null,action text not null check(action in('acknowledge','retry','resolve')),before_state jsonb,after_state jsonb,created_at timestamptz not null default now());alter table public.timeline_daw_normalization_operator_receipts enable row level security;create policy timeline_daw_normalization_operator_receipts_owner on public.timeline_daw_normalization_operator_receipts for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create or replace function public.claim_next_timeline_daw_normalization_render(p_worker text,p_lease_token text,p_lease_seconds integer default 120) returns setof public.timeline_daw_normalization_render_jobs language plpgsql security definer set search_path=public as $$ begin if current_user not in('service_role','postgres') then raise exception 'service role required';end if;return query update public.timeline_daw_normalization_render_jobs j set state='rendering',lease_token=p_lease_token,lease_owner=p_worker,lease_expires_at=now()+make_interval(secs=>greatest(15,least(p_lease_seconds,300))),heartbeat_at=now(),attempt=j.attempt+1,updated_at=now() where j.id=(select x.id from public.timeline_daw_normalization_render_jobs x where not x.cancel_requested and x.artifact_checksum is null and coalesce(x.failure_class,'retryable')<>'terminal' and (x.next_attempt_at is null or x.next_attempt_at<=now()) and (x.state in('queued','failed') or(x.state='rendering' and x.lease_expires_at<now())) order by x.created_at for update skip locked limit 1)returning j.*;end $$;